const http=require('node:http'),fs=require('node:fs'),path=require('node:path');
const defaults={enabled:false,frequency:'daily',timeZone:'America/Sao_Paulo',windowStart:'00:00',windowEnd:'06:00',maxDurationSeconds:120,maxFiles:12000,batchSize:100,pauseMillis:30,includePaths:['/usr/java','/opt'],excludePaths:['/proc','/sys','/dev'],inspectArchives:false};
async function startFixture(webRoot){
 const environments=[{id:'env-a',name:'Production',description:'Production Java estate',settings:{maxFiles:15000},createdAt:'2026-10-09T12:00:00Z',revision:1},{id:'env-b',name:'Development',description:'Development machines',settings:{maxDurationSeconds:180,includePaths:['/opt/dev']},createdAt:'2026-10-09T12:00:00Z',revision:1}];
 const hosts=[{id:'host-a',hostname:'prod-host',distribution:'Red Hat Enterprise Linux Server release 5.11',osName:'Linux',environmentId:'env-a',settingsOverrides:{batchSize:50},coverage:{status:'complete',warnings:[],lastAssessmentAt:'2026-10-09T17:00:00Z',stats:{filesVisited:111,durationMillis:1000}}},{id:'host-b',hostname:'dev-host',distribution:'Oracle Linux Server 8.10',osName:'Linux',environmentId:'env-b',settingsOverrides:{},coverage:{status:'partial',warnings:['Dev path permission note'],lastAssessmentAt:'2026-10-09T18:00:00Z',stats:{filesVisited:222,durationMillis:2000}}},{id:'host-c',hostname:'unassigned-host',environmentId:'',settingsOverrides:{maxFiles:7777},coverage:{status:'pending',warnings:[],stats:{}}}].map(h=>({...h,credentialStatus:'active',registeredAt:'2026-10-09T10:00:00Z',lastSeen:'2026-10-09T20:00:00Z',disks:[],installation:{status:'installed',events:[]}}));
 const state={fleet:{name:'environment-fixture',description:'Isolated environment test'},environments,hosts,settings:{...defaults},serverTime:'2026-10-09T20:00:00Z',coverage:{status:'partial',warnings:['Global fixture note'],stats:{}},enrollments:[{id:'code-a',environmentId:'env-a',label:'Production bootstrap',status:'active'},{id:'code-b',environmentId:'env-b',label:'Development bootstrap',status:'active'},{id:'code-c',environmentId:'',label:'Generic enrollment',status:'active'}],runtimes:[{id:'r-a1',hostId:'host-a',version:'1.6.0_45',javaHome:'/usr/java/java6'},{id:'r-a2',hostId:'host-a',version:'1.8.0_401',javaHome:'/usr/java/java8'},{id:'r-b',hostId:'host-b',version:'21.0.12',javaHome:'/opt/dev/java21'},{id:'r-c',hostId:'host-c',version:'17.0.12',javaHome:'/opt/java17'}]};
 ['servers','applications','libraries','datasources','processes','jobs'].forEach(kind=>state[kind]=hosts.map((h,i)=>({id:kind+'-'+h.id,hostId:h.id,name:kind+' '+h.hostname,type:kind==='servers'?'WebLogic':'Fixture',version:'1.0',state:'RUNNING',status:'SUCCEEDED',observedAt:'2026-10-09T18:00:00Z',createdAt:'2026-10-09T18:00:00Z',driverName:kind==='datasources'?'Fixture JDBC':undefined,driverVersion:kind==='datasources'?'1.0':undefined,summary:'Fixture collection'})));
 const f={state,requests:[],failNextPackage:false,packageCount:0,failNextDelete:'',deleteDelay:0};
 function update(){environments.forEach(e=>{e.settingsOverrides={...e.settings};e.effectiveSettings={...state.settings,...e.settings};});hosts.forEach(h=>{const env=environments.find(e=>e.id===h.environmentId);h.environmentName=env?.name || 'Sem ambiente';h.settings={...state.settings,...(env?.settings || {}),...h.settingsOverrides};});}update();
 const server=http.createServer(async(req,res)=>{const url=new URL(req.url,'http://127.0.0.1');const json=(status,obj)=>{res.writeHead(status,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify(obj));};
  if(url.pathname.startsWith('/api/')){let payload='';for await(const b of req)payload+=b;let body={};try{if(payload)body=JSON.parse(payload);}catch(_){return json(400,{error:'Bad JSON'});}f.requests.push({method:req.method,path:url.pathname,body,csrf:req.headers['x-csrf-token']});if(url.pathname==='/api/session')return json(200,{authenticated:true,csrfToken:'fixture-csrf'});if(req.method!=='GET'&&req.headers['x-csrf-token']!=='fixture-csrf')return json(403,{error:'Missing CSRF'});if(url.pathname==='/api/state'){update();return json(200,state);}
   if(url.pathname==='/api/environments'&&['POST','PUT'].includes(req.method)){const existing=environments.find(e=>e.id===body.environmentId);if(req.method==='PUT'&&!existing)return json(404,{error:'Environment not found'});if(environments.some(e=>e!==existing&&e.name.toLowerCase()===body.name?.toLowerCase()))return json(409,{error:'An environment with this name already exists.'});if(req.method==='POST'){const e={id:'env-'+(environments.length+1),name:body.name,description:body.description,settings:body.settings,revision:1};environments.push(e);update();return json(201,e);}Object.assign(existing,{name:body.name??existing.name,description:body.description??existing.description,settings:body.settings??existing.settings,revision:existing.revision+1});update();return json(200,existing);}
   if(url.pathname==='/api/environments'&&req.method==='DELETE'){if(f.deleteDelay)await new Promise(resolve=>setTimeout(resolve,f.deleteDelay));if(f.failNextDelete){const message=f.failNextDelete;f.failNextDelete='';return json(409,{error:message});}const index=environments.findIndex(e=>e.id===body.environmentId);if(index<0)return json(404,{error:'Environment not found.'});const env=environments[index];if(body.confirmationName!==env.name)return json(409,{error:'The environment name changed. Confirm its current name.'});if(hosts.some(h=>h.environmentId===env.id))return json(409,{error:'Move all machines before deleting this environment.'});state.enrollments.filter(e=>e.environmentId===env.id).forEach(e=>e.status='revoked');environments.splice(index,1);update();return json(200,{deleted:true,environmentId:env.id});}
   if(url.pathname==='/api/hosts/environment'){const h=hosts.find(h=>h.id===body.hostId);if(!h)return json(404,{error:'Host not found'});h.environmentId=body.environmentId;update();return json(200,h);}
   if(url.pathname==='/api/hosts/settings'){const h=hosts.find(h=>h.id===body.hostId);if(!h)return json(404,{error:'Host not found'});h.settingsOverrides=body.replaceOverrides?body.settings:{...h.settingsOverrides,...body.settings};update();return json(200,h.settings);}
   if(url.pathname==='/api/environments/package'){if(f.failNextPackage){f.failNextPackage=false;return json(400,{error:'Package issuance unavailable in the fixture. Retry later.'});}f.packageCount++;const comment=Buffer.from('fixture-bootstrap-secret-'+f.packageCount),zip=Buffer.alloc(22);zip.writeUInt32LE(0x06054b50,0);zip.writeUInt16LE(comment.length,20);res.writeHead(200,{'Content-Type':'application/zip','Content-Disposition':'attachment; filename="assessment-environment-'+body.environmentId+'.zip"','Cache-Control':'no-store'});return res.end(Buffer.concat([zip,comment]));}
   return json(404,{error:'Unexpected fixture endpoint'});
  }
  const filename=url.pathname==='/'?'index.html':url.pathname.slice(1);if(!['index.html','version.js','styles.css','dashboard.css','dashboard.js','app.js','enrollment.css','enrollment.js','environments.css','environments.js'].includes(filename)){res.writeHead(404);return res.end();}res.writeHead(200,{'Content-Type':filename.endsWith('.js')?'application/javascript':filename.endsWith('.css')?'text/css':'text/html','Cache-Control':'no-store'});res.end(fs.readFileSync(path.join(webRoot,filename)));
 });await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));f.base='http://127.0.0.1:'+server.address().port;f.close=()=>new Promise(resolve=>server.close(resolve));return f;
}
module.exports={startFixture};
